import { vi, test, expect } from 'vitest';
import { addItem } from './cart';
vi.mock('./db');
test('adds', () => { expect(addItem(1)).toBe(1); });

import { test, expect } from '@playwright/test';
test.describe.configure({ retries: 2 });
test('buy', async ({ page }) => { await page.goto('/cart'); await page.waitForTimeout(500); expect(page).toHaveURL('/done'); });

import { calc } from './price';
test.skip(!isLocalMode, 'requires local stack');
test.only('a', () => { expect(calc(2)).toBe(4); });
test.skip('b', () => { expect(calc(3)).toBe(6); });

import { calcTax } from './tax';
test('tax', () => {
  expect(calcTax(100)).toBe(calcTax(100));
  if (ready) expect(calcTax(50)).toBe(5);
});

import { vi, test, expect } from 'vitest';
test('farm', () => {
  vi.stubGlobal('fetch', () => Promise.resolve({ status: 200 }));
  const now = Date.now();
  expect([200, 404]).toContain(now);
});

import { test, expect } from 'vitest';
test('nothing', () => {
  expect(1 + 1).toBe(2);
});

import { test, expect } from '@playwright/test';
test('t1', async ({page}) => { await page.goto('/a'); expect(page).toHaveURL('/a'); });
test('t2', async ({page}) => { await page.goto('/b'); expect(page).toHaveURL('/b'); });
test('t3', async ({page}) => { await page.goto('/c'); expect(page).toHaveURL('/c'); });
test('t4', async ({page}) => { await page.goto('/d'); expect(page).toHaveURL('/d'); });
test('t5', async ({page}) => { await page.goto('/e'); expect(page).toHaveURL('/e'); });

import { test, expect } from 'vitest';
import { applyDiscount } from '../../src/discount';
test('discount', () => { expect(applyDiscount(100, 10)).toBe(90); });

import { test, expect } from 'vitest';
import { applyDiscount } from './discount';
test.each([[100, 10, 90], [0, 10, 0]])('applies discount', (price, pct, expected) => {
  expect(applyDiscount(price, pct)).toBe(expected);
});
